import {routeCase,safeUrl,CASES,STATES} from './rules.mjs';
const $=id=>document.getElementById(id);let active='financial';let state='failed';let catalogBusy=false;
function node(tag,text,cls){const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n}
function link(text,url,cls){const a=node('a',text,cls);const safe=safeUrl(url);if(!safe)throw new Error('Destino no permitido');a.href=safe;a.target='_blank';a.rel='noopener noreferrer';return a}
function render(){const c=routeCase(active,state);const result=$('result');result.replaceChildren();result.append(node('p','CASO FICTICIO · DEMO ACADÉMICA','print-label'),node('span',c.state.title,'status'),node('p',c.state.description,'evidence-disclaimer'),node('p',c.tag,'case-tag'));const title=node('h2',c.next);title.id='cardHeading';result.append(title,node('p',c.story,'story'),node('p',c.institution,'institution'));const list=node('ol',undefined,'steps');c.steps.forEach((step,i)=>{const li=node('li');const input=node('input');input.type='checkbox';input.id='step-'+i;const label=node('label',(i+1)+'. '+step);label.htmlFor=input.id;li.append(input,label);list.append(li)});result.append(list,link(c.routeTitle+' ↗',c.route,'route-link'));const source=node('div',undefined,'source');source.append(link(c.sourceTitle,c.source),node('p',(c.stale?'Fuente pendiente de nueva revisión · ':'Fuente revisada · ')+c.reviewed+(c.stale?' · Procedimiento actual no verificado':''),c.stale?'stale':''));result.append(source,node('p',c.limit,'limit'));$('stateDescription').textContent=c.state.description;$('humanText').textContent=c.human;$('explanation').textContent=c.explanation;$('explanation').hidden=true;$('explain').textContent='Explícamelo más sencillo';$('actionFeedback').textContent='';}
function setCase(caseId,stateId=state){routeCase(caseId,stateId);active=caseId;state=stateId;document.querySelectorAll('input[name=case]').forEach(n=>{n.checked=n.value===active});$('evidence').value=state;render();return {caseId:active,evidenceState:state,institution:CASES[active].institution};}
document.querySelectorAll('input[name=case]').forEach(n=>n.addEventListener('change',()=>setCase(n.value)));
$('evidence').addEventListener('change',e=>setCase(active,e.target.value));
$('reset').addEventListener('click',()=>{setCase('financial','failed');$('actionFeedback').textContent='Práctica reiniciada. Se borraron las marcas de esta tarjeta.'});
$('print').addEventListener('click',()=>window.print());
$('explain').addEventListener('click',()=>{$('explanation').hidden=!$('explanation').hidden;$('explain').textContent=$('explanation').hidden?'Explícamelo más sencillo':'Ocultar explicación';});
$('catalog').addEventListener('click',async()=>{if(catalogBusy)return;catalogBusy=true;$('catalog').disabled=true;$('catalogStatus').textContent='Consultando catálogo público. Esto no consulta tu identidad.';const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),8000);try{const r=await fetch('https://haveibeenpwned.com/api/v3/latestbreach',{signal:controller.signal,credentials:'omit',referrerPolicy:'no-referrer'});if(!r.ok)throw new Error('HTTP '+r.status);const data=await r.json();if(typeof data.Title!=='string'||typeof data.BreachDate!=='string'||!Array.isArray(data.DataClasses))throw new Error('Formato no reconocido');const title=data.Title.slice(0,100);const classes=data.DataClasses.filter(s=>typeof s==='string').slice(0,8).map(s=>s.slice(0,50)).join(', ');$('catalogStatus').textContent='Metadatos públicos consultados: '+title+' · Fecha informada: '+data.BreachDate.slice(0,10)+' · Tipos de datos: '+classes+'. Este catálogo no determina si una persona está afectada. La tarjeta ficticia no cambia.';}catch{$('catalogStatus').textContent='No se pudo comprobar el catálogo público. Puede estar fuera de línea o bloquear esta consulta. No significa que tu identidad esté segura. La tarjeta ficticia no cambia.';}finally{clearTimeout(timer);catalogBusy=false;$('catalog').disabled=false;}});
render();
if(document.modelContext?.registerTool){const life=new AbortController();window.addEventListener('pagehide',()=>life.abort(),{once:true});Promise.resolve(document.modelContext.registerTool({name:'configure_fictional_case',title:'Elegir caso ficticio',description:'Cambia únicamente el caso ficticio y su estado de evidencia visibles. No realiza trámites ni consulta identidades.',inputSchema:{type:'object',properties:{caseId:{type:'string',enum:Object.keys(CASES)},evidenceState:{type:'string',enum:Object.keys(STATES)}},required:['caseId','evidenceState'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['caseId','evidenceState'].includes(k)))throw new Error('Entrada no válida');return setCase(input.caseId,input.evidenceState);}},{signal:life.signal})).catch(()=>{});}
